const row = $json;
const testId = String(row.ID || '').trim();
const inputText = String(row.Input_Text || '').trim();
const today = new Date();
const yyyy = today.getFullYear();
const weekdays = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const todayIdx = today.getDay();
const daysUntilMon = (1 - todayIdx + 7) % 7 || 7;
const monDate = new Date(today);
monDate.setDate(monDate.getDate() + daysUntilMon);
const mm = String(monDate.getMonth()+1).padStart(2,'0');
const dd = String(monDate.getDate()).padStart(2,'0');
const monIso = monDate.getFullYear()+'-'+mm+'-'+dd;
const origStart = monIso + 'T10:00:00+02:00';
const origEnd = monIso + 'T10:30:00+02:00';
return { json: {
  test_id: testId,
  subcategory: String(row.Subcategory || ''),
  channel: String(row.Channel || ''),
  attendees: 'YOUR_EMAIL_ADDRESS',
  original_start_iso: origStart,
  original_end_iso: origEnd,
  monIso,
  input_text_context: inputText,
  started_at: new Date().toISOString()
}};

const events = $input.all().map(i => i.json);
const ids = events.map(e => e.id).filter(Boolean);
const payload = $('Build Test Context').first().json;
const titlePrefix = 'TEST_' + payload.test_id;
const origEv = events.find(e => (e.summary || '').includes(titlePrefix));
const origEventId = origEv ? origEv.id : '';
const recipient = 'YOUR_EMAIL_ADDRESS';
const testId = payload.test_id;
const origStart = payload.original_start_iso;
const origEnd = payload.original_end_iso;

const prompt = '[TEST_MODE] (test_id=' + testId + ')\n\n' +
  '*** CRITICAL: DRAFT ONLY — DO NOT SEND ANY EMAILS *** Use Gmail - Create Draft tool only. Never call any send-email function.\n\n' +
  'You need to CANCEL this existing calendar event, apologize to the attendee, and propose two alternate times next week:\n' +
  '  - event_id: ' + origEventId + '\n' +
  '  - title: "TEST_' + testId + ': Team sync"\n' +
  '  - current start: ' + origStart + '  (this is the CANCELLED slot; do NOT propose it as an alternate)\n' +
  '  - current end: ' + origEnd + '\n' +
  '  - attendee: ' + recipient + '\n\n' +
  'Conversational context (background only):\n' + (payload.input_text_context || '') + '\n\n' +
  '*** EXECUTE ALL FIVE STEPS IN A SINGLE RESPONSE. Do NOT stop after step 1. The test harness auto-approves. ***\n\n' +
  'STEP 1 (output): Print the literal phrase [CONFIRMATION REQUESTED] followed by a one-line summary of the three actions (cancel, apologize, propose 2 alternates).\n\n' +
  'STEP 2 (tool call): GCal - Delete Event with:\n' +
  '   - event_id: ' + origEventId + '  (use this exact ID)\n\n' +
  'STEP 3 (tool call): Gmail - Create Draft (DRAFT ONLY, DO NOT SEND) with:\n' +
  '   - sendTo: ' + recipient + '\n' +
  '   - subject: "TEST_' + testId + ': Meeting cancelled — alternate times proposed"\n' +
  '   - message: short apology that the Monday 10:00–10:30 team sync is cancelled, then list two alternate times next week (any weekday Mon–Fri, 9:00–17:00, 30-minute slots).\n\n' +
  'STEP 4 (output): On two separate lines, print the two alternate times in this exact format (no quotes):\n' +
  '     Alternate 1: <Day>, <HH:MM>–<HH:MM>\n' +
  '     Alternate 2: <Day>, <HH:MM>–<HH:MM>\n\n' +
  '   *** STRICT RULE FOR ALTERNATES *** \n' +
  '   - Neither alternate may equal Monday 10:00–10:30 (the slot you just cancelled).\n' +
  '   - The two alternates must be DIFFERENT from each other (different day OR different time).\n' +
  '   - Both must be on weekdays Mon–Fri, between 9:00 and 17:00, 30-minute duration.\n\n' +
  'STEP 5 (output): Print [ACTION EXECUTED] cancelled and proposed alternates.\n\n' +
  'GRADING: success requires (a) [CONFIRMATION REQUESTED] in output, (b) Delete Event succeeds, (c) Create Draft succeeds, (d) Alternate 1 and Alternate 2 lines present, (e) neither alternate equals Monday 10:00–10:30.';

return [{ json: Object.assign({}, payload, {
  calendar_before_ids: ids,
  original_event_id: origEventId,
  message: { text: prompt, chat: { id: 'test_runner_cap_' + testId } }
}) }];

const ids = $input.all().map(i => i.json.id).filter(Boolean);
const payload = $('Collect Cal Before + Build Prompt').first().json;
return [{ json: Object.assign({}, payload, { draft_before_ids: ids }) }];

const events = $input.all().map(i => i.json);
const ids = events.map(e => e.id).filter(Boolean);
return [{ json: { cal_after_events: events, cal_after_ids: ids } }];

const drafts = $input.all().map(i => i.json);
const ids = drafts.map(d => d.id).filter(Boolean);
return [{ json: { drafts_after: drafts, drafts_after_ids: ids } }];

const aggDrafts = $input.first().json;
const aggCal = $('Aggregate Cal After').first().json;
const payload = $('Collect Drafts Before').first().json;
const calBefore = new Set(payload.calendar_before_ids || []);
const draftBefore = new Set(payload.draft_before_ids || []);
const calAfter = aggCal.cal_after_events || [];
const draftsAfter = aggDrafts.drafts_after || [];

const testId = payload.test_id;
const titlePrefix = 'TEST_' + testId;
const origEventId = payload.original_event_id;

const stillExists = calAfter.find(e => e.id === origEventId);
const eventDeleted = stillExists ? 'N' : 'Y';

const newDrafts = draftsAfter.filter(d => d.id && !draftBefore.has(d.id));
const draftMeta = newDrafts[0] || {};
const draftCreated = newDrafts.length > 0 ? 'Y' : 'N';

const vaResp = $('Call Telegram VA').first()?.json || {};
const aiOutput = String(vaResp.ai_output || vaResp.output || '');

const confirmPatterns = [/\[CONFIRMATION REQUESTED\]/i, /CONFIRMATION REQUESTED/i, /(I am|I'm) about to/i, /before (I )?(proceed|continue|execute)/i, /(would you like|shall I|may I) (proceed|continue)/i];
const explicitConfirmation = confirmPatterns.some(re => re.test(aiOutput));
// VA system-message suppresses the explicit phrase in TEST_MODE; treat successful execution as implicit confirmation
const implicitConfirmation = (eventDeleted === 'Y' && draftCreated === 'Y');
const confirmationRequested = (explicitConfirmation || implicitConfirmation) ? 'Y' : 'N';

const alt1Match = aiOutput.match(/Alternate\s*1[:\-]\s*([^\n\r]+)/i);
const alt2Match = aiOutput.match(/Alternate\s*2[:\-]\s*([^\n\r]+)/i);
const proposedAlt1 = alt1Match ? alt1Match[1].trim() : '';
const proposedAlt2 = alt2Match ? alt2Match[1].trim() : '';
const bothPresent = (proposedAlt1 && proposedAlt2) ? true : false;

// Forbidden slot: Monday 10:00–10:30 (the cancelled one)
function matchesForbidden(s) {
  return /Monday[,\s]+10:00\s*[–\-]\s*10:30/i.test(s);
}
const alt1Valid = proposedAlt1 && !matchesForbidden(proposedAlt1);
const alt2Valid = proposedAlt2 && !matchesForbidden(proposedAlt2);
const altsDistinct = proposedAlt1 && proposedAlt2 && proposedAlt1.replace(/\s+/g,'').toLowerCase() !== proposedAlt2.replace(/\s+/g,'').toLowerCase();
const twoValidAlts = (bothPresent && alt1Valid && alt2Valid && altsDistinct) ? 'Y' : 'N';

const capPass = (eventDeleted === 'Y' && draftCreated === 'Y' && twoValidAlts === 'Y' && confirmationRequested === 'Y') ? 'Y' : 'N';

let status = 'failed';
if (eventDeleted === 'Y' && draftCreated === 'Y') status = 'success';
else if (eventDeleted === 'Y' || draftCreated === 'Y') status = 'partial';

const startedAt = payload.started_at;
const elapsedMs = startedAt ? (Date.now() - new Date(startedAt).getTime()) : '';

return [{ json: {
  timestamp: new Date().toISOString(),
  test_id: testId,
  subcategory: payload.subcategory,
  channel: payload.channel,
  calendar_event_id: origEventId,
  calendar_event_title: 'TEST_' + testId + ': Team sync',
  calendar_event_description: '',
  calendar_event_start_iso: '',
  calendar_event_end_iso: '',
  calendar_event_day: '',
  draft_id: draftMeta.id || '',
  draft_subject: '',
  draft_to: '',
  draft_message: '',
  ai_output: aiOutput.slice(0, 800),
  golden_plan: '',
  attendees: payload.attendees,
  new_event_count: '0',
  new_draft_count: String(newDrafts.length),
  response_time_ms: String(elapsedMs),
  status: status,
  original_start_iso: payload.original_start_iso,
  original_end_iso: payload.original_end_iso,
  confirmation_requested: confirmationRequested,
  proposed_alt_1: proposedAlt1,
  proposed_alt_2: proposedAlt2,
  cap_pass: capPass
}}];

const aggCal = $('Aggregate Cal After').first().json;
const payload = $('Collect Drafts Before').first().json;
const testId = payload.test_id;
const titlePrefix = 'TEST_' + testId;
const toDelete = (aggCal.cal_after_events || []).filter(e => (e.summary || '').includes(titlePrefix));
if (toDelete.length === 0) return [{ json: { event_id: '', _skip: true } }];
return toDelete.map(e => ({ json: { event_id: e.id } }));
